#!/usr/bin/env node

/**
 * Lovable Project Detector
 *
 * Detects if a project was generated by Lovable (formerly GPT Engineer)
 * with 95% confidence targeting based on:
 *
 * - Primary Signature (95% confidence):
 *   1. npm package: lovable-tagger present in devDependencies
 *   2. vite.config.ts contains componentTagger import/usage
 *
 * - Secondary Signatures (80% confidence):
 *   1. Directory: src/integrations/supabase/ exists
 *   2. Package: @supabase/supabase-js in dependencies
 *   3. Components: src/components/ui/ with shadcn/ui pattern
 *
 * - Tertiary Signatures (60% confidence):
 *   1. React 18+/19+ + TypeScript + Vite + Tailwind combo
 *   2. Port 8080 in vite.config
 *   3. tsconfig.json with @ path alias
 *
 * Usage:
 *   node lovable-detector.js /path/to/project
 *   node lovable-detector.js . (current directory)
 */

import fs from 'fs/promises';
import fsSync from 'fs';
import path from 'path';

export class LovableDetector {
  constructor() {
    this.priority = 2; // High priority
  }

  /**
   * Main detection method
   * @param {string} projectRoot - Project root directory
   * @returns {Promise<Object>} Detection result
   */
  async detect(projectRoot) {
    this.projectRoot = projectRoot;
    this.indicators = {
      strong: 0,
      medium: 0,
      weak: 0
    };
    this.findings = [];

    try {
      // Run all checks
      await this.checkPackageJson();
      await this.checkViteConfig();
      await this.checkSupabaseIntegration();
      await this.checkComponentStructure();
      await this.checkTsConfig();
      await this.checkConfigurations();

      const confidence = this.calculateConfidence();

      return {
        tool: confidence >= 0.5 ? 'lovable' : null,
        confidence,
        evidence: this.findings.map(f => f.message),
        metadata: {
          framework: 'react',
          buildTool: 'vite',
          backend: 'supabase',
          language: 'typescript',
          styling: 'tailwind'
        },
        indicators: this.findings,
        score: {
          strong: this.indicators.strong,
          medium: this.indicators.medium,
          weak: this.indicators.weak
        }
      };
    } catch (error) {
      return {
        tool: null,
        confidence: 0,
        error: error.message,
        evidence: [],
        metadata: {}
      };
    }
  }

  /**
   * Check package.json for Lovable-specific dependencies
   * PRIMARY DETECTION SIGNATURE: lovable-tagger = 95% confidence
   */
  async checkPackageJson() {
    try {
      const packagePath = path.join(this.projectRoot, 'package.json');
      const content = await fs.readFile(packagePath, 'utf-8');
      const pkg = JSON.parse(content);

      // PRIMARY: lovable-tagger (95% confidence)
      if (pkg.devDependencies?.['lovable-tagger']) {
        this.indicators.strong += 3;
        this.findings.push({
          type: 'strong',
          message: `lovable-tagger v${pkg.devDependencies['lovable-tagger']} found (PRIMARY SIGNATURE)`,
          file: 'package.json',
          confidence: 0.95
        });
      }

      // SECONDARY: Supabase client library
      if (pkg.dependencies?.['@supabase/supabase-js']) {
        this.indicators.medium += 2;
        this.findings.push({
          type: 'medium',
          message: `@supabase/supabase-js v${pkg.dependencies['@supabase/supabase-js']} detected`,
          file: 'package.json',
          confidence: 0.80
        });
      }

      // SECONDARY: React Router (common in Lovable)
      if (pkg.dependencies?.['react-router-dom']) {
        this.indicators.medium += 1;
        this.findings.push({
          type: 'medium',
          message: `react-router-dom v${pkg.dependencies['react-router-dom']} detected`,
          file: 'package.json',
          confidence: 0.70
        });
      }

      // TERTIARY: React 18+/19+
      if (pkg.dependencies?.react) {
        const majorVersion = parseInt(pkg.dependencies.react.match(/\d+/)?.[0] || '0');
        if (majorVersion >= 18) {
          this.indicators.weak += 1;
          this.findings.push({
            type: 'weak',
            message: `React v${pkg.dependencies.react} (18+ typical for Lovable)`,
            file: 'package.json',
            confidence: 0.60
          });
        }
      }

      // SECONDARY: Vite build tool
      if (pkg.devDependencies?.vite) {
        this.indicators.medium += 1;
        this.findings.push({
          type: 'medium',
          message: `Vite v${pkg.devDependencies.vite} detected`,
          file: 'package.json',
          confidence: 0.70
        });
      }

      // SECONDARY: Tailwind CSS
      if (pkg.devDependencies?.tailwindcss) {
        this.indicators.medium += 1;
        this.findings.push({
          type: 'medium',
          message: `Tailwind CSS v${pkg.devDependencies.tailwindcss} detected`,
          file: 'package.json',
          confidence: 0.70
        });
      }

      // SECONDARY: Radix UI components (shadcn/ui dependency)
      const radixIndicators = [
        '@radix-ui/react-dialog',
        '@radix-ui/react-dropdown-menu',
        '@radix-ui/react-slot'
      ];
      let radixCount = 0;
      const foundRadix = [];

      radixIndicators.forEach(dep => {
        if (pkg.dependencies?.[dep]) {
          radixCount++;
          foundRadix.push(dep.replace('@radix-ui/react-', ''));
        }
      });

      if (radixCount >= 2) {
        this.indicators.medium += 1;
        this.findings.push({
          type: 'medium',
          message: `${radixCount} Radix UI dependencies (shadcn/ui) detected: ${foundRadix.join(', ')}`,
          file: 'package.json',
          confidence: 0.75
        });
      }

      // SECONDARY: TypeScript
      if (pkg.devDependencies?.typescript) {
        this.indicators.weak += 0.5;
        this.findings.push({
          type: 'weak',
          message: `TypeScript v${pkg.devDependencies.typescript} detected`,
          file: 'package.json',
          confidence: 0.65
        });
      }

    } catch (error) {
      // package.json not found or invalid
    }
  }

  /**
   * Check vite.config.ts for componentTagger
   * PRIMARY DETECTION SIGNATURE: componentTagger = 95% confidence
   */
  async checkViteConfig() {
    try {
      // Try vite.config.ts first (TypeScript)
      let viteConfigPath = path.join(this.projectRoot, 'vite.config.ts');
      let viteContent = null;

      try {
        viteContent = await fs.readFile(viteConfigPath, 'utf-8');
      } catch (e) {
        // Try vite.config.js (JavaScript)
        viteConfigPath = path.join(this.projectRoot, 'vite.config.js');
        try {
          viteContent = await fs.readFile(viteConfigPath, 'utf-8');
        } catch (e2) {
          return; // No vite config found
        }
      }

      // PRIMARY: componentTagger import/usage (95% confidence)
      if (viteContent && viteContent.includes('componentTagger')) {
        this.indicators.strong += 3;
        this.findings.push({
          type: 'strong',
          message: 'componentTagger import detected in vite.config (PRIMARY SIGNATURE)',
          file: viteConfigPath,
          confidence: 0.95
        });
      }

      // SECONDARY: lovable-tagger import
      if (viteContent && viteContent.includes('lovable-tagger')) {
        this.indicators.strong += 2;
        this.findings.push({
          type: 'strong',
          message: 'lovable-tagger import detected in vite.config',
          file: viteConfigPath,
          confidence: 0.90
        });
      }

      // SECONDARY: Port 8080 configuration (typical Lovable default)
      if (viteContent && viteContent.includes('port: 8080')) {
        this.indicators.weak += 1;
        this.findings.push({
          type: 'weak',
          message: 'Port 8080 configured in vite.config (Lovable default)',
          file: viteConfigPath,
          confidence: 0.60
        });
      }

      // SECONDARY: @ path alias
      if (viteContent && viteContent.includes('@')) {
        this.indicators.weak += 0.5;
        this.findings.push({
          type: 'weak',
          message: '@ path alias configured in vite.config',
          file: viteConfigPath,
          confidence: 0.60
        });
      }

    } catch (error) {
      // Error checking vite config
    }
  }

  /**
   * Check for Supabase integration directory
   * SECONDARY DETECTION SIGNATURE: 80% confidence
   */
  async checkSupabaseIntegration() {
    try {
      const supabaseClientPath = path.join(this.projectRoot, 'src', 'integrations', 'supabase', 'client.ts');

      try {
        const content = await fs.readFile(supabaseClientPath, 'utf-8');

        // Check for supabase client creation
        if (content.includes('createClient') && content.includes('@supabase/supabase-js')) {
          this.indicators.strong += 2;
          this.findings.push({
            type: 'strong',
            message: 'Supabase client initialization found in src/integrations/supabase/client.ts',
            file: 'src/integrations/supabase/client.ts',
            confidence: 0.85
          });
        }
      } catch (e) {
        // Client file not found, but directory structure check will catch it
      }

      // Check for Supabase directory structure
      const supabaseDir = path.join(this.projectRoot, 'src', 'integrations', 'supabase');
      try {
        const stats = await fs.stat(supabaseDir);
        if (stats.isDirectory()) {
          this.indicators.medium += 2;
          this.findings.push({
            type: 'medium',
            message: 'Supabase integration directory found at src/integrations/supabase/',
            file: 'src/integrations/supabase/',
            confidence: 0.80
          });
        }
      } catch (e) {
        // Directory doesn't exist
      }

    } catch (error) {
      // Error checking Supabase integration
    }
  }

  /**
   * Check for shadcn/ui component structure
   * SECONDARY DETECTION SIGNATURE: 60-75% confidence
   */
  async checkComponentStructure() {
    try {
      const uiComponentPath = path.join(this.projectRoot, 'src', 'components', 'ui');

      try {
        const entries = await fs.readdir(uiComponentPath, { withFileTypes: true });
        const componentFiles = entries.filter(e =>
          e.isFile() && (e.name.endsWith('.tsx') || e.name.endsWith('.ts'))
        );

        if (componentFiles.length > 0) {
          this.indicators.medium += 1;
          this.findings.push({
            type: 'medium',
            message: `shadcn/ui components directory found with ${componentFiles.length} components`,
            file: 'src/components/ui/',
            examples: componentFiles.slice(0, 3).map(f => f.name),
            confidence: 0.75
          });

          // Check for common shadcn/ui component files
          const commonComponents = ['button.tsx', 'card.tsx', 'dialog.tsx'];
          const foundCommon = componentFiles.filter(f =>
            commonComponents.some(c => f.name === c)
          );

          if (foundCommon.length >= 2) {
            this.indicators.weak += 1;
            this.findings.push({
              type: 'weak',
              message: `Common shadcn/ui components found: ${foundCommon.map(f => f.name).join(', ')}`,
              file: 'src/components/ui/',
              confidence: 0.70
            });
          }
        }
      } catch (e) {
        // Directory doesn't exist
      }

      // Check for components.json (shadcn/ui config)
      const componentsJsonPath = path.join(this.projectRoot, 'components.json');
      try {
        const content = await fs.readFile(componentsJsonPath, 'utf-8');
        const json = JSON.parse(content);

        this.indicators.medium += 1;
        this.findings.push({
          type: 'medium',
          message: 'components.json found (shadcn/ui configuration)',
          file: 'components.json',
          confidence: 0.75
        });
      } catch (e) {
        // File not found
      }

    } catch (error) {
      // Error checking component structure
    }
  }

  /**
   * Check tsconfig.json for Lovable patterns
   */
  async checkTsConfig() {
    try {
      const tsconfigPath = path.join(this.projectRoot, 'tsconfig.json');
      const content = await fs.readFile(tsconfigPath, 'utf-8');
      const tsconfig = JSON.parse(content);

      // Check for @ path alias (common in Lovable)
      if (tsconfig.compilerOptions?.paths?.['@/*']) {
        this.indicators.weak += 1;
        this.findings.push({
          type: 'weak',
          message: 'Path aliases (@/) configured in tsconfig.json',
          file: 'tsconfig.json',
          confidence: 0.65
        });
      }

      // Check for strict mode (Lovable default)
      if (tsconfig.compilerOptions?.strict === true) {
        this.indicators.weak += 0.5;
        this.findings.push({
          type: 'weak',
          message: 'TypeScript strict mode enabled',
          file: 'tsconfig.json',
          confidence: 0.60
        });
      }

    } catch (error) {
      // tsconfig.json not found or invalid
    }
  }

  /**
   * Check configuration files
   */
  async checkConfigurations() {
    try {
      // Check for tailwind.config.ts
      const tailwindPath = path.join(this.projectRoot, 'tailwind.config.ts');
      try {
        await fs.access(tailwindPath);
        this.indicators.weak += 1;
        this.findings.push({
          type: 'weak',
          message: 'tailwind.config.ts file found',
          file: 'tailwind.config.ts',
          confidence: 0.65
        });
      } catch (e) {
        // File not found
      }

      // Check for .env.example with Supabase config
      const envExamplePath = path.join(this.projectRoot, '.env.example');
      try {
        const content = await fs.readFile(envExamplePath, 'utf-8');
        if (content.includes('SUPABASE')) {
          this.indicators.medium += 1;
          this.findings.push({
            type: 'medium',
            message: 'Supabase environment variables in .env.example',
            file: '.env.example',
            confidence: 0.75
          });
        }
      } catch (e) {
        // File not found
      }

      // Check for TypeScript configuration targeting ES2020 (Lovable pattern)
      const tsconfigPath = path.join(this.projectRoot, 'tsconfig.json');
      try {
        const content = await fs.readFile(tsconfigPath, 'utf-8');
        const tsconfig = JSON.parse(content);
        if (tsconfig.compilerOptions?.target === 'ES2020') {
          this.indicators.weak += 0.5;
          this.findings.push({
            type: 'weak',
            message: 'TypeScript target: ES2020 (Lovable pattern)',
            file: 'tsconfig.json',
            confidence: 0.60
          });
        }
      } catch (e) {
        // File not found
      }

    } catch (error) {
      // Error checking configurations
    }
  }

  /**
   * Calculate confidence score (0-1)
   * Weighted toward primary signatures
   */
  calculateConfidence() {
    const total =
      this.indicators.strong * 3 +
      this.indicators.medium * 1.5 +
      this.indicators.weak * 0.5;

    // Normalize to 0-1 scale
    // High weight for strong indicators (primary signatures worth ~9 points each)
    const maxScore = 18; // Reasonable max for typical Lovable projects
    return Math.min(total / maxScore, 1.0);
  }

  /**
   * Get all findings with sorting by confidence
   */
  getFindings() {
    return this.findings.sort((a, b) => {
      const confidenceOrder = { strong: 3, medium: 2, weak: 1 };
      return confidenceOrder[b.type] - confidenceOrder[a.type];
    });
  }

  /**
   * Format and display results
   */
  displayResults(result) {
    console.log('\n╔════════════════════════════════════════════════════════╗');
    console.log('║        LOVABLE PROJECT DETECTION RESULTS               ║');
    console.log('╚════════════════════════════════════════════════════════╝\n');

    console.log(`Project Root: ${this.projectRoot}`);
    console.log(`Detection Status: ${result.tool ? '✓ Lovable Project' : '✗ Not a Lovable Project'}`);
    console.log(`Confidence Score: ${(result.confidence * 100).toFixed(1)}%\n`);

    if (result.error) {
      console.log(`Error: ${result.error}\n`);
      return;
    }

    // Display findings grouped by type
    const byType = {
      strong: [],
      medium: [],
      weak: []
    };

    result.indicators.forEach(indicator => {
      byType[indicator.type].push(indicator);
    });

    if (byType.strong.length > 0) {
      console.log('STRONG INDICATORS (Primary Lovable Signatures):');
      byType.strong.forEach(ind => {
        console.log(`  ✓ ${ind.message} (${(ind.confidence * 100).toFixed(0)}%)`);
        if (ind.file) console.log(`    File: ${ind.file}`);
      });
      console.log();
    }

    if (byType.medium.length > 0) {
      console.log('MEDIUM INDICATORS (Supporting Evidence):');
      byType.medium.forEach(ind => {
        console.log(`  ○ ${ind.message} (${(ind.confidence * 100).toFixed(0)}%)`);
        if (ind.file) console.log(`    File: ${ind.file}`);
      });
      console.log();
    }

    if (byType.weak.length > 0) {
      console.log('WEAK INDICATORS (Common but not Definitive):');
      byType.weak.forEach(ind => {
        console.log(`  · ${ind.message} (${(ind.confidence * 100).toFixed(0)}%)`);
        if (ind.file) console.log(`    File: ${ind.file}`);
      });
      console.log();
    }

    // Score breakdown
    console.log('Score Breakdown:');
    console.log('─────────────────────────────────────────────────────────');
    console.log(`  Strong Indicators:  ${result.score.strong}`);
    console.log(`  Medium Indicators:  ${result.score.medium}`);
    console.log(`  Weak Indicators:    ${result.score.weak}`);
    console.log();

    // Interpretation
    console.log('Interpretation:');
    console.log('─────────────────────────────────────────────────────────');
    if (result.confidence >= 0.9) {
      console.log('✓ VERY LIKELY a Lovable-generated project');
    } else if (result.confidence >= 0.8) {
      console.log('✓ LIKELY a Lovable-generated project');
    } else if (result.confidence >= 0.6) {
      console.log('◆ POSSIBLY a Lovable-generated project');
    } else if (result.confidence >= 0.4) {
      console.log('◇ SOME Lovable-related characteristics detected');
    } else {
      console.log('✗ NOT likely a Lovable-generated project');
    }
    console.log();
  }
}

/**
 * Main entry point
 */
async function main() {
  const args = process.argv.slice(2);
  const projectRoot = args[0] || '.';

  try {
    // Verify project exists
    await fs.access(projectRoot);
  } catch (error) {
    console.error(`Error: Project root not found: ${projectRoot}`);
    process.exit(1);
  }

  const detector = new LovableDetector();
  const result = await detector.detect(projectRoot);

  detector.displayResults(result);

  // Exit with appropriate code
  process.exit(result.tool ? 0 : 1);
}

// Run if executed directly
if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch(err => {
    console.error('Fatal error:', err);
    process.exit(1);
  });
}

export default LovableDetector;
